"""처음 오셨나요 / 바우처 · 비용"""
from kit import *

def guide():
    body = sec(head("이용 순서", "<span class=\"nb\">시작은</span> <span class=\"nb\"><em class=\"mark\">전화 한 통</em>입니다</span>", "온라인 예약은 받지 않습니다. 전화로 예약한 뒤 방문해 주세요.") + steps([
        ("전화로 예약합니다", f"아이의 나이와 걱정되는 점을 들려주세요. {TEL} · 전화 문의 {CALL_HOURS}"),
        ("방문해서 상담합니다", "예약한 날 연구소에서 아이의 지금 모습을 함께 살펴봅니다. 말이 늦은 아이는 언어발달 평가로 상태를 확인합니다."),
        ("목표를 정합니다", "아이의 발달 수준과 특성, 강점을 살펴 아이마다 목표를 정합니다."),
        ("수업을 시작합니다", "어려운 기술은 작은 단계로 나누어, 충분히 되풀이하며 배웁니다. 집에서 함께 연습할 것도 이야기합니다.")]))
    body += sec(head("이런 경우 상담을 권합니다", "<span class=\"nb\">하나라도 마음에 걸린다면</span> <span class=\"nb\">물어보세요</span>", "어디에 해당하는지 몰라도 괜찮습니다. 전화로 먼저 이야기해 주세요.") + checks([
        f'또래보다 말이 늦다 <a class="tlink" href="{href("speech")}">말 · 언어</a>', f'표현이 제한적이고 의사소통이 어렵다 <a class="tlink" href="{href("aac")}">그림으로 말하기</a>',
        f'집중이 어렵고 학습 기초가 부족하다 <a class="tlink" href="{href("learning")}">읽기 · 학습</a>', f'또래와 관계 맺기가 어렵다 <a class="tlink" href="{href("group")}">그룹 활동</a>',
        f'발달지연이 의심된다 <a class="tlink" href="{href("aba")}">행동 · 조기교실</a>', "영유아 건강검진에서 늦다는 항목이 있었다"]), "sec-soft")
    body += sec(head("전화하기 전에", "<span class=\"nb\">이것만 정리해 두면</span> <span class=\"nb\">통화가 쉬워집니다</span>") + figure("g-w-read", "소파에 나란히 앉아 그림책을 함께 보는 엄마와 아이의 뒷모습", "", "wide") + cards([
        ("아이의 나이", "생년월과 다니는 기관(어린이집 · 유치원 · 학교)."), ("걱정되는 점", "언제부터, 어떤 상황에서 그런지 한두 가지."), ("받은 검사 · 진단", "영유아 건강검진 결과나 병원 진단이 있다면."), ("바우처", "쓰고 있거나 신청하려는 바우처가 있는지.")]))
    body += sec(head("자주 묻는 질문", "<span class=\"nb\">먼저</span> <span class=\"nb\">궁금해하시는 것들</span>") + faq([
        ("진단을 받지 않았어도 상담할 수 있나요?", "<p>네. 또래보다 말이 늦거나 발달이 걱정되는 단계에서도 상담을 권합니다. 다만 연구소의 상담과 평가는 진단이 아니며, 진단은 의료기관에서 받으셔야 합니다.</p>"),
        ("바우처로 이용할 수 있나요?", f'<p>발달재활서비스(보건복지부)와 교육청 치료지원(굳센카드)을 쓸 수 있는 제공기관입니다. 유형별 금액은 <a class="tlink" href="{href("voucher")}">바우처 · 비용</a>에서 보실 수 있습니다.</p>'),
        ("어떤 수업부터 시작해야 할지 모르겠어요.", "<p>방문 상담에서 아이의 지금 모습을 보고 함께 정합니다. 연구소에는 언어 · 인지 · 음악 · 미술 영역이 있습니다.</p>"),
        ("집에서는 무엇을 하면 좋을까요?", "<p>수업에서 배운 것은 집에서도 함께 연습할 때 자리 잡습니다. 아이가 요구를 표현하면 바로 반응해 주고, 눈 맞춤을 시도하면 칭찬해 주는 것처럼 일상에서 되풀이할 수 있는 것을 선생님이 안내합니다.</p>"),
        ("그룹 수업은 언제 하나요?", f'<p>사회성 그룹 · 학교 준비반 · 방학 특별활동은 시기마다 모집합니다. 처음 오시는 경우 예약 상담을 한 뒤 그룹으로 이어집니다. <a class="tlink" href="{href("group")}">그동안의 기록</a></p>'),
        ("주차할 수 있나요?", f'<p>건물 주차장을 이용할 수 있습니다. 지하철은 4호선 상계역에서 걸어서 9분입니다. <a class="tlink" href="{href("location")}">오시는 길</a></p>'),
        ("전화가 안 될 때는요?", f"<p>전화 문의는 {CALL_HOURS}에 받습니다. 수업 중에는 받지 못할 수 있으니 잠시 뒤 다시 걸어 주세요.</p>")]), "sec-soft")
    body += call_band()
    return subpage("guide", "<span class=\"nb\">처음 오셨나요</span>", "전화 예약부터 첫 수업까지, 어떻게 진행되는지 안내합니다.", body, kicker="이용 안내", shape="a")

def voucher():
    R50 = [("다", "26만", "55,000", "없음"), ("가", "24만", "50,600", "17,600"), ("나", "22만", "46,800", "32,800"), ("라", "20만", "42,400", "50,400"), ("마", "18만", "38,000", "68,000")]
    R60 = [("다", "26만", "65,000", "없음"), ("가", "24만", "60,000", "20,000"), ("나", "22만", "55,000", "40,000"), ("라", "20만", "50,000", "60,000"), ("마", "18만", "45,000", "80,000")]
    H = ["유형", "지원금", "회당 결제금액", "본인부담금"]
    mk = lambda rows: table(H, [(f"{a} 유형", b + "원", c + "원", f'<span class="em">{d}{"원" if d != "없음" else ""}</span>') for a, b, c, d in rows])
    price = f'''<div class="pick" data-pick>
  <div class="seg" role="group" aria-label="수업 시간"><span class="seg-ind"></span><button type="button" data-set="m50" class="on" aria-pressed="true">50분 수업</button><button type="button" data-set="m60" aria-pressed="false">60분 수업</button></div>
  <div data-pane="m50">{mk(R50)}</div><div data-pane="m60" hidden>{mk(R60)}</div>
  {note(f"<b>{PRICE_DATE}.</b> 연구소가 안내한 발달재활서비스 단가표를 옮긴 것입니다. 본인부담금은 한 달 4회 기준이며, 유형은 주민센터에서 소득 기준에 따라 정해집니다. 금액은 바뀔 수 있으니 이용 전에 전화로 확인해 주세요.", "warm")}
</div>'''
    body = sec(head("쓸 수 있는 바우처", "<span class=\"nb\">두 가지 바우처의</span> <span class=\"nb\">제공기관입니다</span>") + figure("g-guide-a", "상담 테이블 위의 차 두 잔과 공책, 두 손을 모은 보호자와 메모하는 선생님", "", "wide") + '<div class="vs">' + "".join(f'<article class="vv rv"><p class="v-by">{by}</p><h3>{t}</h3>{kv(rows, "slim")}</article>' for t, by, rows in [
        ("발달재활서비스", "보건복지부 · 2011년부터 제공", [("대상", "만 18세 미만 장애아동 중 발달재활서비스 선정자<br><small>만 9세 미만 발달지연 아동도 신청할 수 있습니다</small>"), ("영역", "언어재활 · 인지재활 · 미술재활 · 음악재활 · 행동재활"), ("신청", "주소지 읍 · 면 · 동 주민센터")]),
        ("치료지원 (굳센카드)", "교육청 · 2012년부터 제공", [("대상", "유 · 초 · 중 · 고등학교 과정의 특수교육대상 학생 가운데 치료지원이 필요한 학생"), ("영역", "언어 · 인지 등 재활 영역"), ("신청", "다니는 학교에 신청")])]) + "</div>")
    body += sec(head("발달재활서비스 금액", "<span class=\"nb\">유형별 지원금과</span> <span class=\"nb\"><em class=\"mark\">내가 내는 돈</em></span>", "수업 시간을 고르면 유형별 금액이 바뀝니다.") + price, "sec-soft")
    body += sec(head("신청 순서", "<span class=\"nb\">발달재활서비스는</span> <span class=\"nb\">주민센터에서 시작합니다</span>") + steps([
        ("주민센터에 신청", "주소지 읍 · 면 · 동 주민센터에 신청합니다."), ("결과 통지", "서비스를 받을 수 있는지와 등급(유형)을 통지받습니다."), ("연구소에 접수", "제공기관인 연구소에 접수한 뒤 수업을 시작합니다.")], "steps-3")
        + note("치료지원(굳센카드)은 학부모가 학교에 신청하면 학교의 개별화교육지원팀에서 지원 여부와 영역을 정합니다. 지원 금액과 절차는 다니는 학교나 교육청에 확인해 주세요. 같은 영역을 두 바우처로 함께 지원받을 수는 없습니다."))
    body += sec(head("자주 묻는 질문", "<span class=\"nb\">바우처에 대해</span> <span class=\"nb\">많이 묻는 것</span>") + faq([
        ("바우처가 없어도 다닐 수 있나요?", "<p>네. 바우처 없이 이용할 때의 수업료는 전화로 문의해 주세요.</p>"),
        ("본인부담금은 언제 내나요?", "<p>본인부담금은 수업을 받기 전에 제공기관에 먼저 내도록 되어 있습니다.</p>"),
        ("어느 유형에 해당하는지 어떻게 아나요?", "<p>유형은 소득 기준에 따라 주민센터에서 정해 통지합니다. 연구소에서는 유형을 정하지 않습니다.</p>"),
        ("진단서가 꼭 있어야 하나요?", "<p>신청에 필요한 서류는 아이의 나이와 상황에 따라 다릅니다. 주민센터에 먼저 물어보시는 것이 정확합니다.</p>")]), "sec-soft")
    body += call_band("바우처 이용, 전화로 물어보세요", "유형과 수업 시간에 따른 금액을 확인해 드립니다.")
    return subpage("voucher", "<span class=\"nb\">바우처 · 비용</span>", "발달재활서비스와 교육청 치료지원(굳센카드)을 쓸 수 있습니다. 유형별 금액을 정리했습니다.", body, kicker="2011년부터 제공기관", shape="b")

def pages(): return [("guide", guide()), ("voucher", voucher())]
